using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using HarborValeGreybox.Driving;
using HarborValeGreybox.Racing;
using HarborValeGreybox.Launch;
namespace HarborValeGreybox.Workshop {
public class AvCameraPlayerProbe:MonoBehaviour {
 static string folder;readonly List<string> lines=new List<string>();bool failed;double deadline;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"--av-camera-check-dir");folder=Debug.isDebugBuild&&i>=0&&i+1<a.Length?Path.GetFullPath(a[i+1]):null;if(folder!=null){Directory.CreateDirectory(folder);DocksideTrialDirector.SavePathOverrideForTests=Path.Combine(folder,"isolated-v5.json");}}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Hook(){if(folder==null)return;var g=new GameObject("Native audiovisual and camera verification");DontDestroyOnLoad(g);g.AddComponent<AvCameraPlayerProbe>();}
 void OnEnable(){Application.logMessageReceived+=Log;}void OnDisable(){Application.logMessageReceived-=Log;}
 void Log(string text,string stack,LogType kind){if(!failed&&(kind==LogType.Error||kind==LogType.Exception)){failed=true;lines.Add("FAIL runtime "+text);Write();Application.Quit(1);}}
 void Check(bool good,string text){lines.Add((good?"PASS ":"FAIL ")+text);if(!good){failed=true;Write();Application.Quit(1);throw new Exception(text);}}
 void Write()=>File.WriteAllLines(Path.Combine(folder,"results.txt"),lines);
 void Update(){if(!failed&&deadline>0&&Time.realtimeSinceStartupAsDouble>deadline)Check(false,"Native audiovisual timeout");}
 IEnumerator Wait(Func<bool> f){while(!f())yield return null;yield return new WaitForSecondsRealtime(.7f);}
 IEnumerator Capture(string name){yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));yield return new WaitForSecondsRealtime(.2f);}
 static TrialSession Finish(TrialDefinition d){var s=new TrialSession(d);s.Tick(4,Vector3.zero,Vector3.zero);s.Tick(90,Vector3.zero,Vector3.zero);foreach(var gate in d.checkpoints)s.Tick(.02f,gate.Position-gate.Forward,gate.Position+gate.Forward);return s;}
 IEnumerator Review(ExpandedWorkshop shop,string name){var car=shop.Car;var chase=car.GetComponent<FinchDrivingHUD>().chase;car.externalInput=true;car.commandedHandbrake=false;chase.externalLookInput=true;Vector3 start=car.Body.position;Quaternion rotation=car.Body.rotation;
  foreach(float angle in new[]{-90f,90f,180f,0f}){chase.commandedLookYaw=angle;yield return new WaitForSecondsRealtime(.8f);Check(Math.Abs(Mathf.DeltaAngle(chase.LookYaw,angle))<1,name+" smooth side/rear/center view "+angle);Check(car.SpeedKph<1,name+" camera does not move or steer car "+angle);if(angle!=0)yield return Capture(name+"_View_"+angle);}
  chase.bonnet=true;chase.commandedLookYaw=90;yield return new WaitForSecondsRealtime(.8f);Check(Vector3.Dot(Camera.main.transform.forward,car.transform.right)>.95f,name+" bonnet camera looks sideways");yield return Capture(name+"_Bonnet_Side");chase.commandedLookYaw=180;yield return new WaitForSecondsRealtime(.8f);yield return Capture(name+"_Bonnet_Rear");chase.bonnet=false;chase.commandedLookYaw=0;chase.Snap();
  Check(shop.Open(),name+" modal opens safely");chase.commandedLookYaw=90;yield return new WaitForSecondsRealtime(.7f);Check(Math.Abs(Mathf.DeltaAngle(chase.LookYaw,0))<1&&!chase.MouseCaptured,name+" modal blocks camera and releases mouse");foreach(var offer in shop.Catalog.MissingPath(shop.Build,shop.Catalog.Find("induction_roots_3")))Check(shop.Install(offer.id),name+" prepared hardware "+offer.id);foreach(var offer in shop.Catalog.MissingPath(shop.Build,shop.Catalog.Find("sound_flame_1")))Check(shop.Install(offer.id),name+" prepared exhaust "+offer.id);shop.Close();chase.commandedLookYaw=25;var fx=car.GetComponent<WorkshopEffects>();var capture=Camera.main.gameObject.AddComponent<TurboNativeAudioTap>();capture.Begin();int beforePull=fx.PopCount;car.commandedPedal=1;car.commandedServiceBrake=1;yield return new WaitForSecondsRealtime(2.5f);Check(fx.SuperGain>.001f&&fx.TurboGain==0,name+" supercharger audio follows installed hardware without turbo layer");car.commandedServiceBrake=0;bool smoke=false;double end=Time.realtimeSinceStartupAsDouble+2.3;while(Time.realtimeSinceStartupAsDouble<end){smoke|=car.IsBurningOut&&car.GetComponent<BurnoutEffects>().ActiveEmitters>0;yield return null;}if(!shop.IsTest)Check(smoke,"Finch measured tire slip produces smoke and squeal");yield return Capture(name+"_Launch_Effects");
  var pivots=new[]{"Front left wheel pivot","Front right wheel pivot","Rear left wheel pivot","Rear right wheel pivot"};float error=0;for(int i=0;i<4;i++){car.Wheels[i].GetWorldPose(out var physical,out _);Vector3 expected=car.transform.TransformPoint(VehicleVisualPose.LocalPosition(car.Body,physical));error=Math.Max(error,Vector3.Distance(car.transform.Find(pivots[i]).position,expected));}lines.Add("MEASURE "+name+" wheel visual error="+error);Check(error<.16f,name+" wheel visuals follow interpolated body without large separation");Check(fx.PopCount==beforePull,name+" automatic shifts do not invent throttle-lift pops");int pops=fx.PopCount;lines.Add("MEASURE "+name+" lift rpm="+car.Engine.Rpm+" shifting="+car.Engine.Shifting+" grounded="+car.GroundedWheels);car.commandedPedal=0;yield return new WaitForSecondsRealtime(.04f);float bright=fx.FlameIntensity;var flare=car.GetComponentsInChildren<MeshRenderer>().First(r=>r.gameObject.name=="Brief exhaust flame visual");float scale=flare.transform.localScale.magnitude;Check(fx.PopCount>pops&&bright>0,name+" actual high-RPM lift creates pop and flame");yield return new WaitForSecondsRealtime(.08f);Check(fx.FlameIntensity<bright&&flare.transform.localScale.magnitude<scale,name+" flame geometry and light fade together");car.commandedServiceBrake=1;yield return new WaitForSecondsRealtime(1.3f);Check(car.GetComponent<BurnoutEffects>().ActiveEmitters==0&&car.GetComponentsInChildren<ParticleSystem>().Sum(p=>p.particleCount)==0,name+" smoke finishes naturally after traction demand ends");var trails=car.GetComponentsInChildren<TrailRenderer>();Check(trails.Length==24,name+" skid effects use bounded six-segment pool per tire");float maxGap=0;foreach(var tr in trails){var points=new Vector3[tr.positionCount];tr.GetPositions(points);for(int i=1;i<points.Length;i++)maxGap=Math.Max(maxGap,Vector3.Distance(points[i],points[i-1]));}Check(maxGap<3,name+" rubber segments contain no long gap bridges");Check(capture.Finish(Path.Combine(folder,name+"_Actual_Mix.wav"))>10000,name+" native listener captures driving mix");Destroy(capture);chase.commandedLookYaw=0;car.ResetAt(start,rotation);yield return new WaitForSecondsRealtime(.2f);float remainingLength=0;foreach(var tr in car.GetComponentsInChildren<TrailRenderer>().Where(t=>t.enabled)){var points=new Vector3[tr.positionCount];tr.GetPositions(points);for(int i=1;i<points.Length;i++)remainingLength+=Vector3.Distance(points[i],points[i-1]);}lines.Add("MEASURE "+name+" reset trail length="+remainingLength+" flame="+fx.FlameIntensity+" throttle="+car.Throttle);Check(remainingLength<.05f&&fx.FlameIntensity==0,name+" recovery clears old visual trails and flames");Check(Math.Abs(Mathf.DeltaAngle(chase.LookYaw,0))<1,name+" recovery recenters camera");Check(car.GetComponentsInChildren<WheelCollider>().Length==4,name+" presentation retains four physical wheel contacts");car.externalInput=false;chase.externalLookInput=false;
 }
 IEnumerator Start(){deadline=Time.realtimeSinceStartupAsDouble+240;yield return Wait(()=>HarborValeLaunch.Instance!=null);HarborValeLaunch.Instance.Open(HarborValeLaunch.CityScene);yield return Wait(()=>FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);var shop=FindAnyObjectByType<ExpandedWorkshop>();var trial=FindAnyObjectByType<DocksideTrialDirector>();for(int i=0;i<60;i++)trial.Store.Settle(Finish(trial.Definition),out _);yield return Review(shop,"Finch");string paid=File.ReadAllText(DocksideTrialDirector.SavePathOverrideForTests);HarborValeLaunch.Instance.Open(HarborValeLaunch.SportsScene);yield return Wait(()=>FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);yield return Review(FindAnyObjectByType<ExpandedWorkshop>(),"Apex");Check(File.ReadAllText(DocksideTrialDirector.SavePathOverrideForTests)==paid,"Free Apex presentation review leaves paid ledger byte-identical");Check(!failed,"No native runtime errors");Write();Application.Quit(0);}
}
}
